def solve_majority(A,maxiter=2):
    h,w=len(A),len(A[0])
    cnt=Counter(v for r in A for v in r)
    out=[r[:] for r in A]
    for it in range(maxiter):
        new=[r[:] for r in out]
        for i in range(h):
            for j in range(w):
                nb=Counter([A[x][y] for x,y in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)) if 0<=x<h and 0<=y<w])
                c,_=nb.most_common(1)[0]
                # replace only if neighborhood has some other color present & differs from own current
                if any(v!=out[i][j] for v,_ in nb.items()):
                    new[i][j]=c
        out=new
    return out
