def prop_voting(I):
    H=len(I);W=len(I[0]);out=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=0: out[r][c]=I[r][c];continue
            best={}
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                x,y=r,c
                while True:
                    x+=dr; y+=dc
                    if not(0<=x<H and 0<=y<W): break
                    v=I[x][y]
                    if v!=0:
                        d=(x-r)**2+(y-c)**2
                        best[v]=(d,len(best.get(v,[])) or 0)
                        break
            if not best: continue
            v=[n for n in best if best[n]==min(best.values())]
            if len(v)>1:
                # tie-break: most candidates? or nearest? try both later
                pass
            out[r][c]=v[0] if len(v)==1 else -1
    return out,out==None
